41	// Joining a wxString to a narrow literal decodes that literal through the
42	// locale's encoding -- UTF-8 on macOS, the ANSI code page on Windows, where
43	// these separators come out as the two or three characters their UTF-8 bytes
44	// happen to spell. Naming them once, decoded explicitly, keeps a separator
45	// from being written the unsafe way again.
46	const wxString& middle_dot() { static const wxString s = wxString::FromUTF8(" \xC2\xB7 "); return s; }
47	const wxString& em_dash()    { static const wxString s = wxString::FromUTF8(" \xE2\x80\x94 "); return s; }
