198	PrintActionState StatusRow::action_state() const
199	{
200	    PrintActionState state;
201	    auto& plates = m_plater.get_partplate_list();
202	    auto* plate = plates.get_curr_plate();
203	    state.slicing = m_plater.is_background_process_slicing();
204	    state.plate_number = plates.get_curr_plate_index() + 1;
205	    state.plate_count = plates.get_plate_count();
206	    const bool editable = !m_plater.only_gcode_mode() && !m_plater.using_exported_file();
207	    for (int i = 0; i < state.plate_count; ++i) {
208	        auto* item = plates.get_plate(i);
209	        if (item->is_slice_result_valid()) ++state.sliced_count;
210	        if (editable && item->can_slice() && !item->is_slice_result_valid()) state.can_slice_all = true;
211	    }
212	    if (plate) {
213	        state.sliced = plate->is_slice_result_valid();
214	        state.can_slice = editable && plate->can_slice();
215	        state.can_print = plate->is_slice_result_ready_for_print();
216	        state.can_export = plate->is_slice_result_ready_for_export();
217	    }
218	    auto* presets = wxGetApp().preset_bundle;
219	    // Match the native print-all backend support. Other legacy hosts accept
220	    // only one plate, even when several valid slices exist.
221	    bool supports_all = presets && presets->use_bbl_network();
222	    if (presets && !supports_all) {
223	        const auto& config = presets->printers.get_edited_preset().config;
224	        const auto* host = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
225	        supports_all = host && host->value == htSimplyPrint;
226	    }
227	    state.can_print_all = supports_all && plates.is_all_slice_results_ready_for_print();
228	    return state;
229	}
