231	wxString StatusRow::action_label(PrintAction action, bool primary) const
232	{
233	    const auto state = action_state();
234	    switch (action) {
235	    case PrintAction::Slice: return _L("Slice");
236	    case PrintAction::SliceAll: return _L("Slice all plates");
237	    case PrintAction::Cancel: return primary ? _L("Slicing…") : _L("Cancel");
238	    case PrintAction::CheckPrint: return _L("Check Print");
239	    case PrintAction::Print: return primary ? (state.plate_count > 1 ? wxString::Format(_L("Print plate %d"), state.plate_number) : _L("Print")) : _L("Print…");
240	    case PrintAction::PrintAll: return _L("Print all plates…");
241	    case PrintAction::Export: return _L("Export sliced file…");
242	    }
243	    throw std::logic_error("Unknown print action");
244	}
