254	void StatusRow::show_action_menu()
255	{
256	    const auto identity = print_target_identity();
257	    const auto state = action_state();
258	    const auto actions = primary_print_action(state);
259	    std::vector<HeaderMenuItem> menu;
260	    for (const auto& item : actions.menu) {
261	        HeaderIcon icon = HeaderIcon::Slice;
262	        if (item.action == PrintAction::CheckPrint) icon = HeaderIcon::Eye;
263	        else if (item.action == PrintAction::Print) icon = HeaderIcon::Print;
264	        else if (item.action == PrintAction::PrintAll || item.action == PrintAction::SliceAll) icon = HeaderIcon::Plates;
265	        else if (item.action == PrintAction::Export) icon = HeaderIcon::Export;
266	        else if (item.action == PrintAction::Cancel) icon = HeaderIcon::Cancel;
267	        wxString detail;
268	        if (item.action == PrintAction::PrintAll)
269	            detail = wxString::Format(_L("%d sliced"), state.sliced_count);
270	        menu.push_back({action_label(item.action), icon, detail, item.enabled, item.action == PrintAction::Export,
271	            [this,identity,action=item.action] {
272	                // The menu describes one plate/result. A later plate switch or
273	                // project replacement must not retarget that displayed command.
274	                if (print_target_identity() == identity) request_action(action);
275	            }});
276	    }
277	    if (!menu.empty()) (new HeaderMenu(this,m_theme,m_dark,std::move(menu)))->open(*m_menu_button);
278	}
