330	void StatusRow::layout_header()
331	{
332	    const int margin = FromDIP(16), gap = FromDIP(8), height = GetClientSize().y;
333	    auto place = [height](HeaderButton* button, int x, int width = -1) {
334	        wxSize size = button->GetBestSize();
335	        if (width >= 0) size.x = width;
336	        button->SetSize(x,(height-size.y)/2,size.x,size.y);
337	    };
338	    int right = GetClientSize().x-margin;
339	    if (m_agent_toggle->IsShown()) {
340	        right -= m_agent_toggle->GetBestSize().x;
341	        place(m_agent_toggle,right);
342	        right -= gap;
343	    }
344	    right -= m_overflow_button->GetBestSize().x;
345	    place(m_overflow_button,right);
346	    right -= gap;
347	    if (m_menu_button->IsShown()) {
348	        right -= m_menu_button->GetBestSize().x;
349	        place(m_menu_button,right);
350	    }
351	    right -= m_slice_button->GetBestSize().x;
352	    place(m_slice_button,right);
353	    int home_x = margin;
354	    if (m_left_pane_toggle->IsShown()) {
355	        place(m_left_pane_toggle, home_x);
356	        home_x += m_left_pane_toggle->GetBestSize().x + gap;
357	    }
358	    place(m_home_button,home_x);
359	    const int left = home_x+m_home_button->GetBestSize().x+gap;
360	    const int available = std::max(0,right-gap-left);
361	    const int width = std::min(m_chip->GetBestSize().x,available);
362	    const wxSize chip = m_chip->GetBestSize();
363	    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
364	}
