388	// The chip renders Orca's own selection and nothing else: the printer, and
389	// one dot per project slot. Nothing here writes; a change goes through the
390	// filament menu and SetupCommands.
391	void StatusRow::refresh_chip()
392	{
393	    const auto printer = SetupCommands::current_printer();
394	    // One nozzle size is said once; a printer with several says each.
395	    std::vector<double> sizes = printer.nozzles;
396	    std::sort(sizes.begin(), sizes.end());
397	    sizes.erase(std::unique(sizes.begin(), sizes.end()), sizes.end());
398	    wxString nozzle;
399	    for (double size : sizes)
400	        nozzle += (nozzle.empty() ? wxString() : wxString(" / ")) + wxString::Format("%g", size);
401	    wxString printer_tooltip = printer.nickname;
402	    if (!nozzle.empty())
403	        printer_tooltip += middle_dot() + nozzle + " mm " + (sizes.size() > 1 ? _L("nozzles") : _L("nozzle"));
404	    m_chip->set_printer(printer.nickname, printer.valid ? nozzle : wxString{}, printer_tooltip);
405	
406	    const auto slots = SetupCommands::filament_slots();
407	    std::vector<ChipSlot> chip_slots;
408	    for (const auto& slot : slots)
409	        chip_slots.push_back({slot.filament.preset_name, std::string(slot.filament.alias.ToUTF8()),
410	                              std::string(slot.colour.ToUTF8()), slot.used});
411	    const FilamentChipModel model = describe_filament_chip(chip_slots);
412	    const wxString label = !model.name.empty() ? wxString::FromUTF8(model.name)
413	                                               : wxString::Format(wxPLURAL("%d filament", "%d filaments", int(model.filaments)),
414	                                                                  int(model.filaments));
415	    // Hover names every slot uncut. The swatches the design draws beside each
416	    // name are the dots on the chip itself; a tooltip carries text only.
417	    wxString tooltip;
418	    if (slots.size() == 1) {
419	        tooltip = slots.front().filament.alias;
420	    } else {
421	        const auto used = std::count_if(slots.begin(), slots.end(), [](const auto& slot) { return slot.used; });
422	        tooltip = used > 0 ? wxString::Format(_L("%d of %d slots on this plate"), int(used), int(slots.size()))
423	                           : wxString::Format(_L("%d slots"), int(slots.size()));
424	        for (const auto& slot : slots) {
425	            tooltip += wxString::Format("\n%d  %s", int(slot.index + 1), slot.filament.alias);
426	            if (slot.nozzle > 0.)
427	                tooltip += middle_dot() + wxString::Format("%g", slot.nozzle);
428	            if (used > 0 && !slot.used)
429	                tooltip += middle_dot() + _L("not on this plate");
430	        }
431	    }
432	    m_chip->set_filaments(model, label, tooltip);
433	}
