451	// One grey line per menu visit that changed a filament, never one per click,
452	// and none for a colour-only visit: the plan did not change. The chip and the
453	// pinned card already follow Orca's own settings-changed notification; the
454	// line reports, and never offers to undo, because the selection belongs to
455	// the chip.
456	void StatusRow::on_filament_visit(const FilamentMenu::Visit& visit)
457	{
458	    refresh();
459	    if (!m_note_sink || visit.filaments.empty()) return;
460	    const auto slots  = SetupCommands::filament_slots();
461	    const bool single = slots.size() == 1;
462	    auto name_of = [&](std::size_t slot) {
463	        return slot < slots.size() ? slots[slot].filament.alias : wxString::FromUTF8(visit.filaments.at(slot));
464	    };
465	    wxString note;
466	    wxString colour;
467	    if (visit.filaments.size() == 1) {
468	        const std::size_t slot = visit.filaments.begin()->first;
469	        note = single ? wxString::Format(_L("Filament is now %s."), name_of(slot))
470	                      : wxString::Format(_L("Slot %d is now %s."), int(slot + 1), name_of(slot));
471	        if (slot < slots.size()) {
472	            colour = slots[slot].colour;
473	            if (!slots[slot].filament.material.empty())
474	                note += " " + wxString::Format(_L("Heat and cooling follow %s; walls and infill unchanged."),
475	                                               slots[slot].filament.material);
476	        }
477	    } else {
478	        wxString changed;
479	        for (const auto& [slot, preset] : visit.filaments)
480	            changed += (changed.empty() ? wxString() : wxString(", ")) +
481	                       wxString::Format(_L("slot %d %s"), int(slot + 1), name_of(slot));
482	        note = wxString::Format(_L("Filaments changed: %s."), changed);
483	    }
484	    note += " " + _L("Slice again when ready.");
485	    m_note_sink(note, colour);
486	}
