514	void StatusRow::show_recent_projects(std::size_t offset)
515	{
516	    if (m_autosave == nullptr)
517	        return;
518	    try {
519	        if (!m_autosave->save_now())
520	            throw std::runtime_error(m_autosave->error());
521	        const auto listed = m_autosave->projects();
522	        if (!listed) {
523	            show_project_error(this, _L("Couldn't load projects"), _L("Projects couldn't be loaded. Try again."),
524	                               "the projects folder could not be read");
525	            return;
526	        }
527	        const auto& projects = *listed;
528	        std::vector<HeaderMenuItem> menu{
529	            {_L("Projects"),HeaderIcon::None,{},false,false,{}},
530	            {_L("Back"),HeaderIcon::Back,{},true,false,[this] { show_overflow_menu(); }}
531	        };
532	        const std::size_t end = std::min(projects.size(), offset + 8);
533	        for (std::size_t index = offset; index < end; ++index) {
534	            const auto& project = projects[index];
535	            wxString label = project.name.empty() || project.name == wxString(_L("Untitled")) ?
536	                _L("Untitled project") : wxString::FromUTF8(project.name);
537	            label += "  " + wxString::FromUTF8(project.updated_at);
538	            if (project.id == m_persistence.document().project_id())
539	                label += _L(" (current)");
540	            menu.push_back({label,HeaderIcon::None,{},true,false,[this, id = project.id] {
541	                if (!m_autosave->open_managed_project(id))
542	                    show_project_error(this, _L("Couldn't open project"),
543	                                       _L("The project couldn't be opened. Try again."), m_autosave->error());
544	                refresh();
545	            }});
546	        }
547	        if (end < projects.size())
548	            menu.push_back({_L("Older projects…"),HeaderIcon::None,{},true,false,[this, end] { show_recent_projects(end); }});
549	        (new HeaderMenu(this,m_theme,m_dark,std::move(menu)))->open(*m_overflow_button);
550	    } catch (const std::exception& error) {
551	        show_project_error(this, _L("Couldn't load projects"),
552	                           _L("Projects couldn't be loaded. Try again."), error.what());
553	    }
554	}
