556	void StatusRow::request_action(PrintAction action)
557	{
558	    const auto actions = primary_print_action(action_state());
559	    const auto eligible = [action](const PrintActionItem& item) { return item.action == action && item.enabled; };
560	    if (!eligible(actions.primary) && std::none_of(actions.menu.begin(), actions.menu.end(), eligible)) return;
561	    switch (action) {
562	    case PrintAction::Slice: request_slice(); return;
563	    case PrintAction::SliceAll: request_slice(true); return;
564	    case PrintAction::Cancel: m_plater.cancel_slicing(); return;
565	    case PrintAction::CheckPrint: {
566	        const auto identity = print_target_identity();
567	        CheckPrintDialog dialog(this, m_theme, m_plater, m_workspace, m_persistence.document().regions(), [this, identity] {
568	            return action_state().sliced && print_target_identity() == identity;
569	        });
570	        dialog.ShowModal();
571	        m_menu_button->SetFocus();
572	        refresh();
573	        return;
574	    }
575	    case PrintAction::Print:
576	    case PrintAction::PrintAll: {
577	        auto& presets = *wxGetApp().preset_bundle;
578	        const auto* host = presets.printers.get_edited_preset().config.option<ConfigOptionString>("print_host");
579	        if (!presets.use_bbl_network() && (!host || host->value.empty())) {
580	            wxMessageBox(_L("Configure a printer connection in Printer settings before printing. You can also export the sliced file."),
581	                         _L("Printer connection required"), wxOK | wxICON_INFORMATION, this);
582	            return;
583	        }
584	        SimpleEvent event(action == PrintAction::Print ? EVT_GLTOOLBAR_PRINT_PLATE : EVT_GLTOOLBAR_PRINT_ALL);
585	        m_plater.GetEventHandler()->ProcessEvent(event); // native confirmation; never an upload shortcut
586	        return;
587	    }
588	    case PrintAction::Export: {
589	        SimpleEvent event(EVT_GLTOOLBAR_EXPORT_SLICED_FILE);
590	        m_plater.GetEventHandler()->ProcessEvent(event);
591	        return;
592	    }
593	    }
594	}
595	
596	void StatusRow::request_slice(bool all)
597	{
598	    const auto state = action_state();
599	    if (state.slicing || state.sliced || (all ? !state.can_slice_all : !state.can_slice)) return;
600	    m_plater.exit_gizmo();
601	    m_plater.update(true, true);
602	    request_prepare();
603	    SimpleEvent event(all ? EVT_GLTOOLBAR_SLICE_ALL : EVT_GLTOOLBAR_SLICE_PLATE);
604	    m_plater.GetEventHandler()->ProcessEvent(event);
605	    refresh();
606	}
