658	void HeaderMenu::build(std::vector<HeaderMenuItem> items)
659	{
660	    const auto palette = m_theme.palette(m_dark);
661	    const PopoverMetrics& popover = m_theme.metrics().popover;
662	    const MenuRowMetrics& menu_row = m_theme.metrics().menu_row;
663	    // A rebuild replaces every row, so drop the old selection rather than
664	    // leaving an index pointing into a destroyed vector.
665	    m_selected = -1;
666	    m_items.clear();
667	    if (auto* old = GetSizer()) {
668	        old->Clear(true);
669	        SetSizer(nullptr, true);
670	    }
671	    m_header = nullptr;
672	
673	    // Rows and separators run the popover's full width inside its border,
674	    // so they never paint over it.
675	    const int row_inset = kPopoverOutlineInset + FromDIP(menu_row.side_inset + popover.border_width);
676	    auto* sizer = new wxBoxSizer(wxVERTICAL);
677	    sizer->AddSpacer(FromDIP(popover.padding_y));
678	    int placed_rows = 0;
679	    bool after_row = false; // the row gap sits only between two consecutive rows
680	    m_header_item_index = -1;
681	    auto place_header = [&] {
682	        if (!m_header_builder || m_header != nullptr) return;
683	        m_header = m_header_builder(this);
684	        // The rows placed so far sit above the view; the next one is the
685	        // first row below it.
686	        m_header_item_index = int(m_items.size());
687	        if (m_header) sizer->Add(m_header,0,wxEXPAND | wxLEFT | wxRIGHT | wxBOTTOM,FromDIP(8));
688	        after_row = false;
689	    };
690	    if (m_header_after_rows == 0) place_header();
691	    for (auto& item : items) {
692	        if (placed_rows == m_header_after_rows) place_header();
693	        if (item.separator) {
694	            auto* line = new wxStaticLine(this);
695	            line->SetForegroundColour(palette.border_subtle);
696	            sizer->AddSpacer(FromDIP(m_theme.metrics().space_1));
697	            sizer->Add(line,0,wxEXPAND | wxLEFT | wxRIGHT,row_inset);
698	            sizer->AddSpacer(FromDIP(m_theme.metrics().space_1));
699	            after_row = false;
700	        }
701	        // A separator-only entry carries no caption of its own.
702	        if (item.title && item.label.empty()) continue;
703	        if (item.title) {
704	            // Eyebrow: a caption, not a row. It takes no focus, no hover, and
705	            // no keyboard stop, so arrow keys skip straight over it.
706	            auto* caption = new wxStaticText(this,wxID_ANY,item.label);
707	            caption->SetFont(m_theme.font(TextRole::Metadata));
708	            caption->SetForegroundColour(palette.text_secondary);
709	            caption->SetBackgroundColour(palette.surface_raised);
710	            sizer->Add(caption,0,wxEXPAND | wxLEFT | wxRIGHT | wxTOP | wxBOTTOM,FromDIP(8));
711	            ++placed_rows;
712	            after_row = false;
713	            continue;
714	        }
715	        auto* button = new HeaderButton(this,m_theme,HeaderStyle::Menu,item.label,item.icon);
716	        button->SetName(item.name.empty() ? item.label : item.name);
717	        item.decoration.detail = item.decoration.detail.empty() ? item.detail : item.decoration.detail;
718	        button->set_decoration(item.decoration);
719	        button->set_dark(m_dark);
720	        button->set_row_action(item.row_action);
721	        button->set_row_action_label(item.row_action_label);
722	        button->Enable(item.enabled);
723	        if (item.invoke_row_action)
724	            button->Bind(wxEVT_MENU,[this,action=std::move(item.invoke_row_action),
725	                                     dismisses=item.dismisses_on_row_action,
726	                                     owner=wxWeakRef<wxWindow>(GetParent())](wxCommandEvent&) {
727	                if (dismisses) {
728	                    close();
729	                    if (owner) owner->CallAfter([owner,action] { if (owner) action(); });
730	                    return;
731	                }
732	                // Like keeps_open rows, this rebuilds the popup's own contents.
733	                // MSVC binds 'this' in a nested lambda's init-capture to the
734	                // enclosing closure, not to HeaderMenu, so name the menu first.
735	                auto* menu = this;
736	                CallAfter([self=wxWeakRef<wxWindow>(menu),action] { if (self) action(); });
737	            });
738	        m_items.push_back(button);
739	        button->Bind(wxEVT_ENTER_WINDOW,[this,index=int(m_items.size()-1)](wxMouseEvent& e) {
740	            if (m_items[index]->IsEnabled()) select_item(index);
741	            e.Skip();
742	        });
743	        if (after_row) sizer->AddSpacer(FromDIP(popover.row_gap));
744	        sizer->Add(button,0,wxEXPAND | wxLEFT | wxRIGHT,row_inset);
745	        ++placed_rows;
746	        after_row = true;
747	        button->Bind(wxEVT_BUTTON,[this,owner=wxWeakRef<wxWindow>(GetParent()),invoke=std::move(item.invoke),
748	                                   keeps_open=item.keeps_open](wxCommandEvent&) {
749	            if (!invoke) return;
750	            if (keeps_open) {
751	                // The handler rebuilds this menu's rows, which destroys the
752	                // button currently delivering this event. Defer past it.
753	                // MSVC binds 'this' in a nested lambda's init-capture to the
754	                // enclosing closure, not to HeaderMenu, so name the menu first.
755	                auto* menu = this;
756	                CallAfter([self=wxWeakRef<wxWindow>(menu),invoke] { if (self) invoke(); });
757	                return;
758	            }
759	            close();
760	            if (owner) owner->CallAfter([owner,invoke] { if (owner) invoke(); });
761	        });
762	    }
763	    place_header(); // a step with fewer rows than requested still gets its view
764	    // The keyboard stays in a view that rebuilt the menu under it.
765	    if (m_header_active) {
766	        if (HeaderMenuKeyView* keys = key_view()) keys->set_key_focus(true);
767	        else m_header_active = false;
768	    }
769	    sizer->AddSpacer(FromDIP(popover.padding_y));
770	    SetSizerAndFit(sizer);
771	    // The first build fixes the width; later rebuilds keep it so swapping to
772	    // the search view does not make the popup jump under the pointer.
773	    if (m_width == 0)
774	        m_width = std::clamp(GetSize().x,FromDIP(m_theme.metrics().popover.width),FromDIP(420));
775	    SetSize(wxSize(m_width,GetSize().y));
776	    Layout();
777	#if defined(__WXOSX__) || defined(__WXMSW__)
778	    // Preserve the actual rounded silhouette (and the compositor's popup
779	    // shadow), rather than painting a rounded border into a square window.
780	    auto outline = wxGraphicsRenderer::GetDefaultRenderer()->CreatePath();
781	    outline.AddRoundedRectangle(0,0,GetSize().x,GetSize().y,FromDIP(popover.radius));
782	    SetShape(outline);
783	#endif
784	}
