301	// How much of a row's width is reserved on the right for everything that is
302	// not the label. Shared by the size calculation and the painter so a row can
303	// never measure one way and paint another.
304	int HeaderButton::trailing_reserve() const
305	{
306	    int reserve = FromDIP(12);
307	    if (!m_row_action_label.empty()) reserve += row_action_rect().width + FromDIP(m_theme.metrics().space_2);
308	    else if (m_row_action != HeaderIcon::None) reserve += FromDIP(20);
309	    if (m_status) reserve += FromDIP(16);
310	    if (m_decoration.check) reserve += FromDIP(20);
311	    if (m_decoration.trailing != HeaderIcon::None) reserve += FromDIP(20);
312	    if (m_decoration.status != StatusTone::None) {
313	        reserve += FromDIP(14); // dot and its gap
314	        if (!m_decoration.status_word.empty()) reserve += GetTextExtent(m_decoration.status_word).x + FromDIP(4);
315	    }
316	    if (!m_decoration.detail.empty() && !m_decoration.detail_inline) {
317	        wxClientDC dc(const_cast<HeaderButton*>(this));
318	        dc.SetFont(detail_font());
319	        reserve += dc.GetTextExtent(m_decoration.detail).x + FromDIP(16);
320	    }
321	    return reserve;
322	}
