447	void OrcaHomeBackend::open_dropped_files(const std::vector<DroppedFile>& files)
448	{
449	    // The page gives a dropped file's bytes but not its path. Each is kept
450	    // under a folder named by its content, so the same file dropped again
451	    // has the same path, and a .3mf among them can be recognized as opened
452	    // before. A file opened from its own folder has a different path.
453	    wxArrayString paths;
454	    for (const DroppedFile& file : files) {
455	        try {
456	            const std::filesystem::path name = std::filesystem::u8path(file.name).filename();
457	            if (name.empty() || name == "." || name == "..")
458	                continue;
459	            const std::filesystem::path root     = std::filesystem::temp_directory_path() / "JusPrin-dropped";
460	            const std::filesystem::path incoming = root / boost::filesystem::unique_path().string() / name;
461	            std::filesystem::create_directories(incoming.parent_path());
462	            std::ofstream(incoming, std::ios::binary).write(file.bytes.data(), std::streamsize(file.bytes.size()));
463	            std::string incoming_name = incoming.u8string(), digest;
464	            if (!bbl_calc_md5(incoming_name, digest) || digest.empty())
465	                throw std::runtime_error("its digest could not be read");
466	            const std::filesystem::path kept = root / digest / name;
467	            if (!std::filesystem::exists(kept)) {
468	                std::filesystem::create_directories(kept.parent_path());
469	                std::filesystem::rename(incoming, kept);
470	            }
471	            std::filesystem::remove_all(incoming.parent_path());
472	            paths.Add(wxString::FromUTF8(kept.u8string()));
473	        } catch (const std::exception& error) {
474	            BOOST_LOG_TRIVIAL(error) << "Home could not keep the dropped file " << file.name << ": " << error.what();
475	            MessageDialog(&m_frame, wxString::Format(_L("%s couldn't be opened. Try opening it with Open… instead."),
476	                                                     wxString::FromUTF8(file.name)),
477	                          _L("Couldn't open file"), wxOK | wxICON_ERROR)
478	                .ShowModal();
479	            return;
480	        }
481	    }
482	    if (!paths.empty())
483	        open_as_new_project(paths);
484	}
