param([string]$In)
Add-Type -AssemblyName System.Drawing
$b = [System.Drawing.Bitmap]::FromFile($In)
function hex($c) { '#{0:X2}{1:X2}{2:X2}' -f $c.R, $c.G, $c.B }
# Column x=600 (inside the menu), top to bottom: where colours change.
$prev = ''
for ($y = 70; $y -lt 305; $y++) {
  $h = hex ($b.GetPixel(600, $y))
  if ($h -ne $prev) { "y=$y $h"; $prev = $h }
}
"--- separator row, left to right"
# The first separator: find the row in 195..215 that differs from the popover ground at x=600.
$ground = hex ($b.GetPixel(600, 125))
for ($y = 195; $y -lt 215; $y++) {
  if ((hex ($b.GetPixel(600, $y))) -ne $ground) {
    $prev = ''
    for ($x = 455; $x -lt 745; $x++) { $h = hex ($b.GetPixel($x, $y)); if ($h -ne $prev) { "x=$x y=$y $h"; $prev = $h } }
    break
  }
}
"--- button and popover edges at y=100"
$prev = ''
for ($x = 700; $x -lt 760; $x++) { $h = hex ($b.GetPixel($x, 100)); if ($h -ne $prev) { "x=$x $h"; $prev = $h } }
"--- ⋯ button column x=724"
$prev = ''
for ($y = 40; $y -lt 95; $y++) { $h = hex ($b.GetPixel(724, $y)); if ($h -ne $prev) { "y=$y $h"; $prev = $h } }
$b.Dispose()

