904	    // user has a visible starting point. Arrows work from either state.
905	    if (anchor.activated_by_keyboard())
906	        for (size_t i=0;i<m_items.size();++i) if (m_items[i]->IsEnabled()) { select_item(int(i)); break; }
907	}
908	
909	void HeaderMenu::reposition()
910	{
911	    if (!m_anchor) return;
912	    const int x = m_align == Align::Left ? 0 : m_anchor->GetSize().x-GetSize().x;
913	    Position(m_anchor->ClientToScreen(wxPoint(x,m_anchor->GetSize().y+FromDIP(4))),wxSize(0,0));
914	}
