406	void HeaderButton::draw(wxDC& dc, wxGraphicsContext& context, const wxSize& client)
407	{
408	    const auto& p = m_theme.palette(m_dark);
409	    const bool primary = m_style == HeaderStyle::PrimaryLeft || m_style == HeaderStyle::PrimaryRight;
410	    const bool chip    = m_style == HeaderStyle::ChipLeft || m_style == HeaderStyle::ChipRight;
411	    const wxColour& ground = m_surface == HeaderSurface::Raised ? p.surface_raised : p.surface_canvas;
412	    dc.SetBackground(wxBrush(m_style == HeaderStyle::Menu ? p.surface_raised : ground));
413	    dc.Clear();
414	    wxGraphicsContext* gc = &context;
415	
416	    const auto foreground = !IsEnabled() ? p.action_disabled_text :
417	                            m_decoration.danger ? p.status_danger :
418	                            primary ? p.action_primary_text :
419	                            m_style == HeaderStyle::Quiet ? p.text_secondary : p.text_primary;
420	    const bool highlighted = (m_hover || m_open || m_menu_selected) && IsEnabled();
421	    wxColour fill = primary ? (!IsEnabled() ? p.action_disabled : m_pressed || m_open ? p.action_primary_pressed :
422	                              m_hover ? p.action_primary_hover : p.action_primary) :
423	                   // A menu row under the pointer or the keyboard is the design
424	                   // system's Menu/Row band; every other control shows its open
425	                   // or hovered state as selected.
426	                   highlighted ? (m_style == HeaderStyle::Menu ? p.surface_raised_hover : p.surface_selected) :
427	                   // The filament half sits on a quieter ground than the printer
428	                   // half, so the chip reads as two things inside one outline.
429	                   m_style == HeaderStyle::ChipRight ? p.surface_subtle :
430	                   m_style == HeaderStyle::Menu ? p.surface_raised : ground;
431	
432	    const ShellMetrics& m = m_theme.metrics();
433	    const double w = client.x, h = client.y;
434	    const double r = FromDIP(primary ? m.radius_medium :
435	                             chip ? m.chip.radius :
436	                             m_style == HeaderStyle::Menu ? m.menu_row.radius :
437	                             m_style == HeaderStyle::Outline ? m.button.icon.radius : m.radius_small);
438	    if (chip) {
439	        // Each half draws the whole chip's rounded rectangle, extended past
440	        // the shared inner edge so only its own outer corners round. The top
441	        // and bottom borders then meet exactly across the seam.
442	        gc->SetPen(wxPen(p.border_subtle));
443	        gc->SetBrush(wxBrush(fill));
444	        gc->DrawRoundedRectangle(m_style == HeaderStyle::ChipLeft ? 0.5 : 0.5 - r, 0.5, w - 1 + r, h - 1, r);
445	        if (m_style == HeaderStyle::ChipRight) {
446	            gc->SetPen(wxPen(p.border_subtle));
447	            gc->StrokeLine(0.5, 0.5, 0.5, h - 0.5);
448	        }
449	    } else {
450	        gc->SetPen(primary || m_style == HeaderStyle::Quiet || m_style == HeaderStyle::Menu ? *wxTRANSPARENT_PEN : wxPen(p.border_subtle));
451	        gc->SetBrush(wxBrush(fill));
452	        gc->DrawRoundedRectangle(0.5,0.5,w-1,h-1,r);
453	    }
454	    if (primary && (m_style == HeaderStyle::PrimaryRight || m_attached)) {
455	        gc->SetPen(*wxTRANSPARENT_PEN);
456	        gc->DrawRectangle(m_style == HeaderStyle::PrimaryLeft ? w-r-1 : 0,0,r+1,h);
457	    }
458	    if (m_style == HeaderStyle::PrimaryRight) {
459	        gc->SetPen(wxPen(p.action_primary_hover));
460	        gc->StrokeLine(0,FromDIP(7),0,h-FromDIP(7));
461	    }
462	
463	    const double icon_size = FromDIP(m.button.icon.icon_size);

