$b = [System.Drawing.Bitmap]::FromFile($In)
function hex($c) { '{0:X2}{1:X2}{2:X2}' -f $c.R, $c.G, $c.B }
foreach ($y in $Rows) {
  $prev = ''; $line = "y=$y "
  for ($x = $X0; $x -lt $X1; $x++) { $h = hex ($b.GetPixel($x, $y)); if ($h -ne $prev) { $line += "$x:$h "; $prev = $h } }
  $line
}
$b.Dispose()

